input.function:
() => {
  // Permission rows on this form are <select> elements named like
  // integration[default_permissions][<api_key>]. Pair each with its visible label.
  const out = [];
  for (const sel of document.querySelectorAll('select[name*="default_permissions"]')) {
    const m = sel.name.match(/default_permissions\]\[([^\]]+)\]/);
    const key = m ? m[1] : sel.name;
    // Walk up to the row container and find its heading text.
    let node = sel, label = '';
    for (let i = 0; i < 8 && node; i++) {
      node = node.parentElement;
      if (!node) break;
      const h = node.querySelector('h4, h3, label, strong, .text-bold');
      if (h && h.textContent.trim()) { label = h.textContent.trim().split('\n')[0]; break; }
    }
    // Section heading (Repository / Organization / Account permissions)
    let sec = '', p = sel;
    while (p) {
      const prev = p.previousElementSibling;
      if (prev) {
        const t = prev.textContent.trim();
        if (/permissions$/i.test(t.split('\n')[0])) { sec = t.split('\n')[0]; break; }
      }
      p = prev || p.parentElement;
    }
    out.push({ key, label, section: sec, options: [...sel.options].map(o => o.value) });
  }
  return { count: out.length, rows: out };
}

() => {
  const selects = [...document.querySelectorAll('select')];
  const radios = [...document.querySelectorAll('input[type=radio]')];
  return {
    title: document.title,
    selectCount: selects.length,
    sampleSelectNames: selects.slice(0, 12).map(s => s.name),
    radioCount: radios.length,
    sampleRadioNames: [...new Set(radios.map(r => r.name))].slice(0, 12),
    headings: [...document.querySelectorAll('h1,h2,h3')].map(h => h.textContent.trim()).slice(0, 25),
  };
}

() => {
  const h = [...document.querySelectorAll('h3,h2,h4')].find(e => /^Repository permissions$/i.test(e.textContent.trim()));
  if (!h) return { error: 'heading not found' };
  // Find the container that holds the permission rows
  let box = h.parentElement;
  for (let i = 0; i < 4 && box && box.textContent.length < 500; i++) box = box.parentElement;
  const html = box ? box.innerHTML.slice(0, 3000) : '';
  return {
    boxTag: box && box.tagName,
    textLen: box && box.textContent.length,
    inputsInside: box ? [...box.querySelectorAll('input,select,button')].slice(0,10).map(e => ({t:e.tagName, type:e.type, name:e.name, aria:e.getAttribute('aria-label')})) : [],
    htmlHead: html,
  };
}

async () => {
  // Expand every collapsed section; permission rows render lazily inside.
  for (const d of document.querySelectorAll('details')) d.open = true;
  await new Promise(r => setTimeout(r, 1200));
  const names = [...new Set([...document.querySelectorAll('input,select')].map(e => e.name).filter(n => n && n.includes('permission')))];
  return {
    detailsCount: document.querySelectorAll('details').length,
    permissionControlNames: names.slice(0, 60),
    total: names.length,
  };
}

() => {
  const want = ['administration','checks','statuses','contents','vulnerability_alerts','issues','metadata','pull_requests','workflows','members'];
  const sectionOf = (el) => {
    let d = el.closest('details');
    const h = d && d.querySelector('h3');
    return h ? h.textContent.trim() : '(unknown)';
  };
  const rows = want.map(key => {
    const ctrls = [...document.querySelectorAll(`[name="integration[default_permissions][${key}]"]`)];
    if (!ctrls.length) return { key, found: false };
    const c = ctrls[0];
    // The row's visible name is the nearest preceding heading-ish element.
    let box = c.closest('li, .Box-row, fieldset') || c.parentElement;
    const legend = box.querySelector('legend, h4, .text-bold');
    const desc = box.querySelector('p');
    const opts = ctrls[0].tagName === 'SELECT'
      ? [...ctrls[0].options].map(o => o.value)
      : ctrls.map(r => r.value);
    return {
      key,
      found: true,
      label: legend ? legend.textContent.trim().split('\n')[0] : '(no legend)',
      section: sectionOf(c),
      control: ctrls[0].tagName === 'SELECT' ? 'select' : 'radio',
      accessOptions: opts,
      description: desc ? desc.textContent.trim().slice(0, 90) : '',
    };
  });
  return rows;
}

() => {
  const c = document.querySelector('[name="integration[default_permissions][statuses]"]');
  let box = c;
  for (let i = 0; i < 6; i++) { box = box.parentElement; if (box && box.textContent.trim().length > 60) break; }
  return {
    tag: box.tagName,
    cls: box.className,
    text: box.textContent.replace(/\s+/g, ' ').trim().slice(0, 400),
    html: box.innerHTML.replace(/\s+/g, ' ').slice(0, 1200),
  };
}

() => {
  const want = ['administration','checks','statuses','contents','vulnerability_alerts','issues','metadata','pull_requests','workflows','members'];
  return want.map(key => {
    const btn = document.querySelector(`button[data-resource="${key}"]`);
    if (!btn) return { key, found: false };
    // Climb to the row that contains both the menu and the permission's name.
    let row = btn;
    for (let i = 0; i < 10; i++) {
      row = row.parentElement;
      if (!row) break;
      const h = row.querySelector('h4, .js-permission-name, [data-permission-name]');
      if (h) return {
        key,
        label: h.textContent.replace(/\s+/g, ' ').trim(),
        parent: btn.getAttribute('data-resource-parent'),
        mandatory: btn.getAttribute('data-mandatory'),
        options: [...row.querySelectorAll(`button[data-resource="${key}"]`)].map(b => b.getAttribute('data-value')),
      };
    }
    // Fallback: first non-empty text node above the menu
    const t = btn.closest('li,div')?.parentElement?.textContent.replace(/\s+/g,' ').trim().slice(0,120);
    return { key, label: '(fallback) ' + t, parent: btn.getAttribute('data-resource-parent') };
  });
}

() => {
  const btn = document.querySelector('button[data-resource="statuses"]');
  let row = btn;
  // Climb until the container's text includes something other than the menu options.
  for (let i = 0; i < 12; i++) {
    row = row.parentElement;
    if (!row) break;
    const txt = row.textContent.replace(/\s+/g, ' ').trim();
    if (!/^No access/.test(txt) && txt.length > 40) {
      return { depth: i, tag: row.tagName, cls: row.className, text: txt.slice(0, 300) };
    }
  }
  return { error: 'not found' };
}

() => {
  const fields = [...document.querySelectorAll('input[name^="integration"], textarea[name^="integration"]')]
    .filter(e => !e.name.includes('default_permissions'))
    .map(e => ({ name: e.name, type: e.type, value: e.value?.slice(0,60), checked: e.checked }));
  const ids = ['none','read','write'].map(v => ({ v, exists: !!document.getElementById(`integration_permission_statuses_${v}`) }));
  return { fields, statusesButtonIds: ids };
}

async () => {
  const setInput = (name, value) => {
    const el = document.querySelector(`[name="${name}"]:not([type=hidden])`);
    if (!el) return `MISSING ${name}`;
    const proto = el.tagName === 'TEXTAREA' ? HTMLTextAreaElement : HTMLInputElement;
    Object.getOwnPropertyDescriptor(proto.prototype, 'value').set.call(el, value);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    el.dispatchEvent(new Event('change', { bubbles: true }));
    return 'ok';
  };

  const log = {};
  log.name = setInput('integration[name]', 'spinor-renovate');
  log.url = setInput('integration[url]', 'https://github.com/hasToggle/spinor');
  log.description = setInput(
    'integration[description]',
    'Self-hosted Renovate runner for hasToggle/spinor. Driven by .github/workflows/renovate.yml on a schedule; no webhook. Replaces the Mend Cloud Runner that covers hasToggle.dev.'
  );

  // No webhook: this runner polls on a schedule.
  const hook = document.querySelector('input[type=checkbox][name="integration[hook_attributes][active]"]');
  if (hook?.checked) { hook.click(); log.webhook = 'unchecked'; } else { log.webhook = 'already off'; }

  // Renovate's documented permission set.
  const perms = {
    administration: 'read',
    checks: 'write',
    contents: 'write',
    issues: 'write',
    members: 'read',
    metadata: 'read',
    pull_requests: 'write',
    statuses: 'write',
    vulnerability_alerts: 'read',
    workflows: 'write',
  };
  log.permissions = {};
  for (const [key, val] of Object.entries(perms)) {
    const btn = document.getElementById(`integration_permission_${key}_${val}`);
    if (!btn) { log.permissions[key] = `MISSING button for ${val}`; continue; }
    btn.click();
    await new Promise(r => setTimeout(r, 60));
    const hidden = document.querySelector(`input[type=hidden][name="integration[default_permissions][${key}]"]`);
    log.permissions[key] = hidden ? hidden.value : 'no hidden input';
  }
  return log;
}

() => {
  const nonNone = [...document.querySelectorAll('input[type=hidden][name*="default_permissions"]')]
    .filter(i => i.value && i.value !== 'none')
    .map(i => [i.name.match(/\[([^\]]+)\]$/)[1], i.value]);
  const events = [...document.querySelectorAll('input[name="integration[default_events][]"]:checked')].map(e => e.value);
  const vis = document.querySelector('input[name="integration[visibility]"]:checked')?.value;
  const hook = document.querySelector('input[type=checkbox][name="integration[hook_attributes][active]"]')?.checked;
  return {
    name: document.querySelector('[name="integration[name]"]').value,
    homepage: document.querySelector('[name="integration[url]"]').value,
    webhookActive: hook,
    visibility: vis,
    eventsSubscribed: events,
    permissionsSet: Object.fromEntries(nonNone),
    permissionCount: nonNone.length,
  };
}

